window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-12791\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτέμνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1552 na letra ε · nº geral 12791</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cortar fora; cortar; extrair por incisão; amputar 2 cortar (árvores); devastar 3 cortar esperanças; frustrar 4 cortar nervos; enfraquecer 5 castrar ♦ méd. pas. 6 castrar: οἱ ἐκτετμημένοι artt. os eunucos.</p></section></article>\n<article id=\"entry-dgp-12792\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτένεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1553 na letra ε · nº geral 12792</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 perseverança; tenacidade; afinco: ἐν ἐκτενείᾳ n.t. com afinco ou perseverança 2 abundância. 〈ἐκτενής〉</p></section></article>\n<article id=\"entry-dgp-12793\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1554 na letra ε · nº geral 12793</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atento; solícito 2 bíbl. premente; veemente (prece). 〈ἐκτείνω〉</p></section></article>\n<article id=\"entry-dgp-12794\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτενῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1555 na letra ε · nº geral 12794</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com solicitidude; com zelo 2 com ardor 3 com abundância 4 prodigamente; esplendidamente; suntuosamente.</p></section></article>\n<article id=\"entry-dgp-12795\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1556 na letra ε · nº geral 12795</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἔχω.</p></section></article>\n<article id=\"entry-dgp-12796\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτέταμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1557 na letra ε · nº geral 12796</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de ἐκτείνω.</p></section></article>\n<article id=\"entry-dgp-12797\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτετμημένος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1558 na letra ε · nº geral 12797</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐκτέμνω.</p></section></article>\n<article id=\"entry-dgp-12798\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτεφρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1559 na letra ε · nº geral 12798</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">reduzir a cinzas. 〈ἐκ, τέφρα〉</p></section></article>\n<article id=\"entry-dgp-12799\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτεχνάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1560 na letra ε · nº geral 12799</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. 3ª sing. ἐξετεχνήσατο) imaginar; inventar.</p></section></article>\n<article id=\"entry-dgp-12800\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτήκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1561 na letra ε · nº geral 12800</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκτήξω, aor. ἐξέτακον, perf ἐκτέτηκα; aor.2 pas. ἐξετάκην) 1 fazer fundir; derreter, ac. 2 fazer consumir-se: ὄμμα δ᾽ ἐκτήξουσ᾽ ἐμὸν δακρύοισι eur. elas [as amigas] farão consumir-se em lágrimas meus olhos, ἐκτ. τινὰ εἰς δάκρυα plut. fazer alguém consumir-se em lágrimas 3 consumir-se: ἐκτ. λύπῃ καὶ λιμῷ ἐαυτόν el. consumir-se em dor e fome 4 fazer desaparecer; apagar; eliminar; abolir ♦ intr. (perf. ἐκτέτηκα) e pas. 5 derreter-se 6 consumir-se: ἐκτέτηκα καρδίαν eur. tenho o coração consumido 7 apagar-se: μοι τόδε μήποτ᾽ ἐκτακείη ésql. que isso [esses pensamentos] jamais se apague de meu espírito.</p></section></article>\n<article id=\"entry-dgp-12801\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτημαι, ἐκτήμην</h1><div class=\"entry-meta\"><span>DGP · ordem 1562 na letra ε · nº geral 12801</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. e m.-q.-perf. jôn. de κτάομαι.</p></section></article>\n<article id=\"entry-dgp-12802\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκτημόριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1563 na letra ε · nº geral 12802</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 a sexta parte de um todo ♦ οἱ ἑκτημόριοι 2 hectêmoros, lavradores da Ática que pagavam como imposto a sexta parte dos rendimentos. 〈ἕκτος, μέρος〉</p></section></article>\n<article id=\"entry-dgp-12803\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτίθημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1564 na letra ε · nº geral 12803</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκθήσω, aor. ἐξέθηκα etc.) 1 pôr para fora de, gen. 2 expor (criança); abandonar alguém em algum lugar 3 fazer conhecer; propor; expor 4 explicar 5 tornar público; publicar; fazer afixar 6 mostrar (marca no próprio corpo) ♦ méd. 7 transportar para fora; exportar 8 expor 9 explicar minuciosamente.</p></section></article>\n<article id=\"entry-dgp-12804\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτιθηνέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1565 na letra ε · nº geral 12804</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">criar; nutrir.</p></section></article>\n<article id=\"entry-dgp-12805\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτίκτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1566 na letra ε · nº geral 12805</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκτέξομαι, perf. ἐκτέτοκα) parir.</p></section></article>\n<article id=\"entry-dgp-12806\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτιμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1567 na letra ε · nº geral 12806</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 honrar grandemente; venerar 2 avaliar bem alto (preço); superestimar; encarecer.</p></section></article>\n<article id=\"entry-dgp-12807\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1568 na letra ε · nº geral 12807</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">privado de honras; sem honras. 〈ἐκ, τιμή〉</p></section></article>\n<article id=\"entry-dgp-12808\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτινάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1569 na letra ε · nº geral 12808</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sacudir; fazer cair 2 procurar ♦ méd. 3 sacudir.</p></section></article>\n<article id=\"entry-dgp-12809\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1570 na letra ε · nº geral 12809</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pagar; liquidar; saldar: ζημίαν ἐκτ. χίλια τάλαντα her. pagar multa de mil talentos, ἐκτ. δίκην eur. pagar, expiar uma pena 2 pagar o preço de algo, ac., a alguém, dat. ou εἰς e ac.: ἐκτ. χάριν eur., ἐκτ. εὐεργεσίην her. pagar o preço de um benefício, i.e., recompensar um benefício, saldar uma dívida de reconhecimento, ἐκτ. βλάβην plat. reparar um dano ♦ méd. 3 fazer pagar; fazer expiar 4 vingar-se de alguém, ac.</p></section></article>\n<article id=\"entry-dgp-12810\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτισα</h1><div class=\"entry-meta\"><span>DGP · ordem 1571 na letra ε · nº geral 12810</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de κτίζω.</p></section></article>\n<article id=\"entry-dgp-12811\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1572 na letra ε · nº geral 12811</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pagamento; quitação: ἔκτισιν ποιεῖσθαι dem. pagar, quitar 2 satisfação; recompensa; punição 3 reparação. 〈ἐκτίνω〉</p></section></article>\n<article id=\"entry-dgp-12812\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτισμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1573 na letra ε · nº geral 12812</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de κτίζω.</p></section></article>\n<article id=\"entry-dgp-12813\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτισσα</h1><div class=\"entry-meta\"><span>DGP · ordem 1574 na letra ε · nº geral 12813</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ἔκτισα.</p></section></article>\n<article id=\"entry-dgp-12814\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτιτρώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1575 na letra ε · nº geral 12814</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκτρώσω) 1 abortar 2 tentar fazer abortar 3 parir antes do tempo.</p></section></article>\n<article id=\"entry-dgp-12815\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτοθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1576 na letra ε · nº geral 12815</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de fora; de longe: οἱ ἔκτοθεν teócr. os de fora 2 fora; longe: ἔκτ. γαμεῖν eur. casar-se num país estrangeiro, ἔκτοθεν αὐλῆς hom. fora no pátio ♦ prep. 3 fora de; afastado de; longe de, gen. 〈ἐκτός, -θεν〉</p></section></article>\n<article id=\"entry-dgp-12816\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτοθι</h1><div class=\"entry-meta\"><span>DGP · ordem 1577 na letra ε · nº geral 12816</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 fora ♦ prep. 2 fora de; longe de; afastado de, gen. 〈ἐκτός, -θι〉</p></section></article>\n<article id=\"entry-dgp-12817\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτοκον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1578 na letra ε · nº geral 12817</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rebento. 〈ἐκτίκτω〉</p></section></article>\n<article id=\"entry-dgp-12818\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτολυπεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1579 na letra ε · nº geral 12818</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desenredar; levar ao fim.</p></section></article>\n<article id=\"entry-dgp-12819\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτομή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1580 na letra ε · nº geral 12819</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 entalhe; corte 2 amputação 3 castração 4 pedaço; segmento: ἐκτομὴ γῆς plut. torrão de terra. 〈ἐκτέμνω〉</p></section></article>\n<article id=\"entry-dgp-12820\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτομίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1581 na letra ε · nº geral 12820</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 castrado; eunuco 2 animal castrado. 〈ἐκτομή〉</p></section></article>\n<article id=\"entry-dgp-12821\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτοξεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1582 na letra ε · nº geral 12821</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 disparar flechas de um local, gen. 2 gastar todas as flechas; ἐκτ. βίον ar. esgotar a vida 3 acertar fora do alvo; não atingir o alvo; afastar-se de, gen.</p></section></article>\n<article id=\"entry-dgp-12822\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτοπίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1583 na letra ε · nº geral 12822</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 colocar fora do lugar; deslocar; afastar 2 deixar o lugar; afastar-se; (animais) emigrar 3 fugir 4 Ret. fazer um desvio: ἐκτ. εἰς μῦθόν τι estr. desviar algo para a fábula, converter algo em fábula ♦ méd. pas. part. perf. ἐκτετοπισμένος 5 afastado; remoto 6 estranho; bizarro. 〈ἔκτοπος〉</p></section></article>\n<article id=\"entry-dgp-12823\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτόπιος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1584 na letra ε · nº geral 12823</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον 1 distante; afastado 2 estrangeiro 3 estranho; extraordinário ♦ ἐκτόπιον adv. 4 fora daqui; longe.</p></section></article>\n<article id=\"entry-dgp-12824\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτοπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1585 na letra ε · nº geral 12824</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 retirado do lugar; deslocado 2 distante; afastado 3 estrangeiro 4 estranho; extraordinário (coisa) 5 extravagante (pessoa). 〈ἐκ, τόπος〉</p></section></article>\n<article id=\"entry-dgp-12825\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτόπως</h1><div class=\"entry-meta\"><span>DGP · ordem 1586 na letra ε · nº geral 12825</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo estranho; de modo extraordinário.</p></section></article>\n<article id=\"entry-dgp-12826\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκτόρεος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1587 na letra ε · nº geral 12826</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Heitor. 〈 Ἕκτωρ〉</p></section></article>\n<article id=\"entry-dgp-12827\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκτορίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1588 na letra ε · nº geral 12827</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Heitor. 〈 Ἕκτωρ〉</p></section></article>\n<article id=\"entry-dgp-12828\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕκτος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1589 na letra ε · nº geral 12828</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. ord. 1 sexto ♦ ὁ ἕκτος [ μήν] 2 o sexto mês; o mês de agosto, entre os romanos. 〈ἕξ〉</p></section></article>\n<article id=\"entry-dgp-12829\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτός</h1><div class=\"entry-meta\"><span>DGP · ordem 1590 na letra ε · nº geral 12829</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 fora: ἐ. ἔρχεσθαι transgredir, violar (uma promessa) ♦ prep. 2 (lugar) fora de, gen.: τειχέος ἐ. hom. fora do muro, ἐ. αὐλῆς hom. fora do pátio 3 (tempo) depois de, gen.: ἐ. πέντε ἡμερέων her. depois de cinco dias 4 fora de; isento de, gen.: ἐ. αἰτίης her. isento de culpa, ἐ. στρατειῶν plat. isento do serviço militar, ἐ. πημάτων sóf. sem sofrimentos, ἐ. ἐλπίδος sóf. contra toda esperança 5 afora; exceto, gen.: ἐ. ὀλίγων xen. exceto um pequeno número, ἐ. εἰ μή luc. a não ser que, a menos que ♦ οἱ ἐκτός 6 os estrangeiros 7 bíbl. os gentios. 〈ἐκ〉</p></section></article>\n<article id=\"entry-dgp-12830\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτοσε</h1><div class=\"entry-meta\"><span>DGP · ordem 1591 na letra ε · nº geral 12830</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 para fora ♦ prep. 2 para fora de, gen.</p></section></article>\n<article id=\"entry-dgp-12831\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτοσθε</h1><div class=\"entry-meta\"><span>DGP · ordem 1592 na letra ε · nº geral 12831</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, diante de vogal, ἔκτοσθεν, adv. 1 de fora; do lado de fora 2 fora; no lado de fora ♦ prep. 3 fora de, gen. 〈ἐκτός, -θε〉</p></section></article>\n<article id=\"entry-dgp-12832\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτραγῳδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1593 na letra ε · nº geral 12832</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 expor ou discorrer em estilo trágico; exagerar 2 declamar (como um ator trágico) 3 gabar alguém, ac., com ênfase 4 retirar a máscara trágica de; desmascarar, ac.</p></section></article>\n<article id=\"entry-dgp-12833\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτράπεζος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1594 na letra ε · nº geral 12833</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">excluído da mesa (alimentos). 〈ἐκ, τράπεζα〉</p></section></article>\n<article id=\"entry-dgp-12834\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπράπελος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1595 na letra ε · nº geral 12834</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">monstruoso; enorme. 〈ἐκτρέπω〉</p></section></article>\n<article id=\"entry-dgp-12835\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτραπῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1596 na letra ε · nº geral 12835</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 pas. de ἐκτρέπω.</p></section></article>\n<article id=\"entry-dgp-12836\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτραχηλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1597 na letra ε · nº geral 12836</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐξετραχήλισα) 1 (cavalo) lançar o cavaleiro, ac., por cima do pescoço; precipitar 2 quebrar o pescoço 3 precipitar na desgraça ♦ pas. 4 quebrar-se o pescoço 5 deixar-se arruinar. 〈ἐκ, τράχηλος〉</p></section></article>\n<article id=\"entry-dgp-12837\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτραχύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1598 na letra ε · nº geral 12837</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar rude; exasperar ♦ pas. 2 irritar-se; exasperar-se contra alguém, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-12838\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτρέπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1599 na letra ε · nº geral 12838</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκτρέψω etc.) 1 desviar; afastar alguém ou algo, ac., de alguém ou de algo, ac., em direção a ou contra, εἰς ou πρός ou ἐπί e ac.: ἐκτ. τοῦ ποταμοῦ τὸ ῥέεθρον πᾶν her. desviar todo a corrente do rio, μηδ᾽ εἰς Ἐλένην κότον ἐκτρέψῃς ésql. nem voltes contra Helena a ira 2 desviar; dissuadir alguém, ac., de, part.: οὔτε ξυνέρδεις τήν τε δρῶσαν ἐκτρέπεις sóf. não cooperas e tentas dissuadir-me de realizar [a vingança] ♦ méd. (aor.2 ἐξετραπόμην) 3 desviar-se ou afastar-se do caminho 4 desviar-se de uma coisa, ἀπό e gen., para outra, ἐπί e ac. 5 desviar-se de; evitar alguém, ac., ou algo, ac. ou inf. 6 mudar-se; passar a, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-12839\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτρέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 1600 na letra ε · nº geral 12839</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκθρέψω etc.) 1 nutrir; criar; alimentar ♦ méd. 2 criar; cuidar de; nutrir em seu corpo.</p></section></article>\n<article id=\"entry-dgp-12840\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτρέχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1601 na letra ε · nº geral 12840</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκθρέξομαι e ἐκδραμοῦμαι, aor.2 ἐξέδραμον) 1 sair correndo 2 (tropa) escapar 3 (planta) brotar; crescer 4 (ira) explodir 5 tard. ultrapassar, ac. 6 perder por precipitação (a ocasião).</p></section></article>\n<article id=\"entry-dgp-12841\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτριαινόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1602 na letra ε · nº geral 12841</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bater com o tridente em; fazer tremer. 〈ἐκ, τρίαινα〉</p></section></article>\n<article id=\"entry-dgp-12842\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτρίβω</h1><div class=\"entry-meta\"><span>DGP · ordem 1603 na letra ε · nº geral 12842</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esfregar uma coisa, ac., em outra, dat. ou ἐν e dat. 2 fazer brotar (esfregando) uma coisa, ac., de outra, ἐκ e gen. 3 retirar esfregando; limpar (mancha); polir (objeto) 4 gastar esfregando; consumir (vida) 5 arrancar; abater; devastar 6 arrancar; exterminar; aniquilar.</p></section></article>\n<article id=\"entry-dgp-12843\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτροπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1604 na letra ε · nº geral 12843</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desvio de, gen. 2 meio de desviar 3 libertação de, gen. 4 ação de desviar; afastamento; digressão em discurso 5 tard. mudança de vida 6 desvio que contorna uma via; atalho; bifurcação. 〈ἐκ, τρέπω〉</p></section></article>\n<article id=\"entry-dgp-12844\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτρυφάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1605 na letra ε · nº geral 12844</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abandonar-se à languidez, à sensualidade; ser efeminado.</p></section></article>\n<article id=\"entry-dgp-12845\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτρυχόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1606 na letra ε · nº geral 12845</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exaurir; consumir; gastar. 〈ἐκ, τρύχω〉</p></section></article>\n<article id=\"entry-dgp-12846\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτρώσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1607 na letra ε · nº geral 12846</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de ἐκτιτρώσκω.</p></section></article>\n<article id=\"entry-dgp-12847\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτρωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1608 na letra ε · nº geral 12847</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fruto que não vingou; feto abortivo. 〈ἐκτιτρώσκω〉</p></section></article>\n<article id=\"entry-dgp-12848\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτρωτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1609 na letra ε · nº geral 12848</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para fazer abortar; abortífero. 〈ἐκτιτρώσκω〉</p></section></article>\n<article id=\"entry-dgp-12849\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτυπον</h1><div class=\"entry-meta\"><span>DGP · ordem 1610 na letra ε · nº geral 12849</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κτυπέω.</p></section></article>\n<article id=\"entry-dgp-12850\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκτυπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1611 na letra ε · nº geral 12850</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 talhado em relevo ♦ τὸ ἔκτυπον 2 esboço. 〈ἐκ, τύπος〉</p></section></article>\n<article id=\"entry-dgp-12851\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτυπόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1612 na letra ε · nº geral 12851</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκτυπώσω, aor. ἐξετύπωσα, perf. desus.; pas. só part. aor. e perf.) 1 moldar; talhar em relevo ♦ méd. 2 modelar; representar conforme um modelo 3 fazer algo, ac., refletir em algo, εἰς e ac.: ὥσπερ εἰς κάτροπτον ἢ ὕδωρ τὴν δόξαν ἐκτυπούμενον εἰς τὴν διὰ τοῦ στόματος ῥοήν plat. fazendo refletir a opinião na torrente que sai da boca, como em um espelho ou em água. 〈ἔκτυπος〉</p></section></article>\n<article id=\"entry-dgp-12852\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτυφλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1613 na letra ε · nº geral 12852</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar cego; cegar ♦ pas. 2 tornar-se cego 3 perder a luz; ser obscurecido 4 destruir os olhos, i.e., os brotos da videira.</p></section></article>\n<article id=\"entry-dgp-12853\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκτύφλωσις, εως</h1><div class=\"entry-meta\"><span>DGP · ordem 1614 na letra ε · nº geral 12853</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, jôn., ιος (ἡ) ação de tornar cego, de cegar. 〈ἐκτυφλόω〉</p></section></article>\n<article id=\"entry-dgp-12854\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕκτωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 1615 na letra ε · nº geral 12854</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que segura fortemente, epít. de Zeus ♦ ὁ ἕκτωρ 2 âncora. 〈ἔχω〉</p></section></article>\n<article id=\"entry-dgp-12855\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἕκτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1616 na letra ε · nº geral 12855</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Heitor, filho de Príamo e Hécuba.</p></section></article>\n<article id=\"entry-dgp-12856\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκυκλεῦντο</h1><div class=\"entry-meta\"><span>DGP · ordem 1617 na letra ε · nº geral 12856</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. méd. jôn. de κυκλέω.</p></section></article>\n<article id=\"entry-dgp-12857\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκυρά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1618 na letra ε · nº geral 12857</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sogra, mãe do marido.</p></section></article>\n<article id=\"entry-dgp-12858\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκυρός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1619 na letra ε · nº geral 12858</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sogro, pai do marido.</p></section></article>\n<article id=\"entry-dgp-12859\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκυρσα</h1><div class=\"entry-meta\"><span>DGP · ordem 1620 na letra ε · nº geral 12859</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κύρω.</p></section></article>\n<article id=\"entry-dgp-12860\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκυσσα</h1><div class=\"entry-meta\"><span>DGP · ordem 1621 na letra ε · nº geral 12860</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ép. de κυνέω.</p></section></article>\n<article id=\"entry-dgp-12861\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1622 na letra ε · nº geral 12861</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκφανῶ, aor. ἐξέφηνα; pas. aor.2 ἐξεφάνην, ép. 3ª sing. ἐξεφαάνθη, 3ª pl. ἐξεφάαντεν) 1 fazer aparecer; fazer nascer: ἐκφ. ἄνδρα φοώσδε hom. dar à luz a um homem, i.e., a um guerreiro, ἐκφ. τινα ἐς ὀφθαλμοὺς ἐμούς sóf. fazer aparecer alguém diante de meus olhos 2 mostrar; fazer ver; revelar; manifestar: τά ἄρρητα ἱρὰ ἐκφ. Μιλτιάδῃ her. revelar os segredos sagrados a Milcíades, ἐκφ. τὴν ἑωυτοῦ γνώμην her. manifestar a própria opinião, πᾶσαν κακότητα ἐξέφαινε ἐς τοὺς πολιήτας her. demonstrava toda maldade contra os cidadãos, ἐκφ. σεαυτὸν ἐόντα τοῦ πατρὸς οὐδὲν ἥσσω her. mostrar que não és em nada inferior a teu pai 3 declarar guerra, ac., a alguém, πρός e ac. ♦ méd. pas. 4 fazer-se ver; aparecer; mostrar-se; revelar-se: ὅ τε δειλὸς ἀνὴρ, ὅς τ᾽ ἄλκιμος ἐξεφαάνθη hom. o homem covarde e também o corajoso se revelaram, δίκαιοι δ᾽ αὖθις ἐκφανοῦμεθα sóf. a seguir nos mostraremos justos, πλευρὰ παρ᾽ ἀσπίδος ἐξεφαάνθη hom. a ilharga do lado do escudo ficou visível 5 brilhar: οἳ ὅσσε δεινὸν ὑπὸ βλεφάρων ὡς εἰ σέλας ἐξεφάανθεν hom. seus olhos, sob as pálpebras, brilharam terrivelmente, como se fossem uma chama.</p></section></article>\n<article id=\"entry-dgp-12862\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1623 na letra ε · nº geral 12862</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (pessoa) que se mostra; que aparece 2 manifesto; visível ♦ τὰ ἐκφανῆ 3 figuras em relevo. 〈ἐκφαίνω〉</p></section></article>\n<article id=\"entry-dgp-12863\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφαντικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1624 na letra ε · nº geral 12863</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para explicar, para fazer ver. 〈ἐκφαίνω〉</p></section></article>\n<article id=\"entry-dgp-12864\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφαντικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1625 na letra ε · nº geral 12864</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo significativo.</p></section></article>\n<article id=\"entry-dgp-12865\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφανῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1626 na letra ε · nº geral 12865</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. manifestamente; visivelmente; evidentemente.</p></section></article>\n<article id=\"entry-dgp-12866\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφάσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1627 na letra ε · nº geral 12866</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἔκφημι.</p></section></article>\n<article id=\"entry-dgp-12867\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκφασις, εως</h1><div class=\"entry-meta\"><span>DGP · ordem 1628 na letra ε · nº geral 12867</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, jôn., ιος (ἡ) declaração. 〈ἔκφημι〉</p></section></article>\n<article id=\"entry-dgp-12868\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφάτως</h1><div class=\"entry-meta\"><span>DGP · ordem 1629 na letra ε · nº geral 12868</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de modo ímpio 2 em voz alta; abertamente. 〈ἔκφημι〉</p></section></article>\n<article id=\"entry-dgp-12869\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφαυλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1630 na letra ε · nº geral 12869</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 depreciar 2 desdenhar de, inf. 〈ἐκ, φαῦλος〉</p></section></article>\n<article id=\"entry-dgp-12870\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφερέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1631 na letra ε · nº geral 12870</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép., ἔκφερεν, ἔκφερον 3ª sing. e 3ª pl. impf. ép., de ἐκφέρω.</p></section></article>\n<article id=\"entry-dgp-12871\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1632 na letra ε · nº geral 12871</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐξοίσω, aor.1 ἐξήνεγκα, jôn. e ép. ἐξήνεικα e ἐξένεικα, aor.2 ἐξήνεγκον; aor. pas. ἐξηνέχθην) 1 levar algo ou alguém, ac., para fora de, gen. ou ἐκ e gen.: ἐκφ. πολέμοιο hom. levar para fora do combate, ἐκφ. ὅπλα ἐκ μεγάρου her. levar armas para fora do palácio 2 levar o morto para sepultar, para os funerais: ἐξέφερον θρασὺν Ἕκτορα hom. levaram à sepultura o valente Heitor 3 levar (o prêmio); obter; ganhar: ἐκφ. ἄεθλον hom. ganhar um prêmio 4 levar; transportar; conduzir para, ἐπί ou εἰς e ac.: τὸν δὲ δελφῖνα λέγουσι ὑπολαβόντα ἐξενεῖκαι ἐπὶ Ταίναρον her. dizem que um golfinho pegou-o e o levou para Tênaro, ἐκφ. εἰς Καππαδοκίαν plut. levar para a Capadócia, ἄτραπος ἡμᾶς ἐκφέρει plat. um atalho nos conduz 5 levar (como tributo); pagar: ἐκφ. δισχίλια τάλαντα pol. pagar dez mil talentos 6 levar a cabo; concluir: ἐκφ. τὸ μόρσιμον pínd. completar o destino 7 (solo, planta) produzir; gerar; fornecer (prova): Δήμητρος καρπὸν ἐκφ. her. produzir o fruto de Deméter, εἰς φῶς ἐκφ. κύημα plat. dar à luz um embrião 8 fazer conhecer; expor a, dat. ou εἰς e ac.; divulgar; publicar: πᾶσιν ἀνθρώποις παράδειγμ᾽ ἐξοίσετε κοινὸν ὑπὲρ τῆς πόλεως dem. divulgareis a todos os homens um exemplo comum à cidade, ἐξενεῖκαι ἐς τὸν δῆμον her. expor ao povo 9 emitir; pronunciar; declamar 10 empreender; levar (guerra) contra alguém, dat. ou ἐπί ou πρός e ac. 11 ir para fora; lançar-se à frente: ἐξέφερον Διομήδεος ἵπποι hom. os cavalos de Diomedes lançavam-se à frente 12 atingir o fim; chegar a termo; (oráculo) cumprir-se: ἐς ὀρθὸν ἐκφέρει μαντεύματα sóf. os oráculos cumprem-se exatamente ♦ méd. (fut. ἐξοίσομαι, aor. ἐξηνεγκάμην) 13 levar embora consigo: τὰ ἑαυτοῦ ἐκφ. tuc. levar consigo os seus pertences 14 conquistar; obter: ἐκφ. κλέος sóf. conquistar a glória 15 manifestar; declarar; apresentar (projeto) diante de, εἰς e ac.: ἐκφ. γνώμην her. manifestar sua opinião, ἐκφ. προβούλευμα εἰς τὴν ἐκκλησίαν ésqn. apresentar o projeto à assembléia ♦ pas. 16 deixar-se arrebatar; deixar-se levar por algo, πρός e ac.: πρὸς ὀργὴν ἐκφέρῃ sóf. tu te deixas levar pela cólera.</p></section></article>\n<article id=\"entry-dgp-12872\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφεύγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1633 na letra ε · nº geral 12872</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fugir; escapar de, gen. ou ἐκ ou ἀπό e gen.: παῦροι δ᾽ ἐξέφυγον πολιῆς ἁλός hom. poucos escaparam do mar espumoso, βέλος ἔκφυγε χειρός hom. o dardo escapou de sua mão 2 escapar de; subtrair-se a; estar isento, livre de, ac.: ἐξέφυγε ὁμοίην νοῦσον her. escapou de uma doença semelhante, Σκύθας ἐκφεύγει her. ele escapou dos Citas, ἁνὴρ ὅδ᾽ ἐκπέφευγεν αἵματος δίκην ésql. este homem está livre de acusação de assassínio, ἐκφεύγοντας τὴν χίονα τόπους pol. lugares livres de neve 3 evitar algo, or. com μή ou μή οὐ e inf.: μικρὸν ἐξέφυγε μὴ καταπετρωθῆναι xen. evitou por pouco ser lapidado, οὐκ ἐκφεύγει μὴ οὐκ ἐπονείδιστον εἶναι plat. não evitou não ser objeto de censura 4 passar despercebido de alguém, ac.: ἐκφεύγει με τοῦτο sóf. isso me escapa.</p></section></article>\n<article id=\"entry-dgp-12873\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκφημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1634 na letra ε · nº geral 12873</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. pres. méd. ἐκφάσθαι) exprimir; pronunciar; dizer.</p></section></article>\n<article id=\"entry-dgp-12874\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφθείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1635 na letra ε · nº geral 12874</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">destruir completamente.</p></section></article>\n<article id=\"entry-dgp-12875\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφθίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1636 na letra ε · nº geral 12875</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esgotar; arruinar completamente ♦ pas. 2 perecer; desaparecer.</p></section></article>\n<article id=\"entry-dgp-12876\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφλαυρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1637 na letra ε · nº geral 12876</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκφαυλίζω.</p></section></article>\n<article id=\"entry-dgp-12877\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφλέγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1638 na letra ε · nº geral 12877</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pôr fogo em; inflamar; abrasar ♦ pas. 2 arder; inflamar-se.</p></section></article>\n<article id=\"entry-dgp-12878\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφοβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1639 na letra ε · nº geral 12878</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 provocar em alguém, ac., medo de algo, ac.; assustar; apavorar ♦ méd. pas. 2 ter medo de alguém, ac.; temer por algo, ὑπέρ e gen.; temer que, or. conj. (ὡς).</p></section></article>\n<article id=\"entry-dgp-12879\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκφοβος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1640 na letra ε · nº geral 12879</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">assustado; apavorado. 〈ἐκ, φόβος〉</p></section></article>\n<article id=\"entry-dgp-12880\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφοιτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1641 na letra ε · nº geral 12880</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ter o hábito de sair; sair; ir-se 2 (coisa) difundir-se; espalhar-se 3 chegar: ἐκφ. εἰς μανίαν el. chegar à loucura.</p></section></article>\n<article id=\"entry-dgp-12881\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφοιτέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1642 na letra ε · nº geral 12881</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐκφοιτάω.</p></section></article>\n<article id=\"entry-dgp-12882\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφορά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1643 na letra ε · nº geral 12882</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 transporte 2 traslado (de corpo); cortejo fúnebre; funeral 3 divulgação; revelação 4 emissão (de voz); expressão; enunciação 5 Gram. pronúncia 6 Gram. palavra derivada. 〈ἐκ, φέρω〉</p></section></article>\n<article id=\"entry-dgp-12883\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1644 na letra ε · nº geral 12883</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 levar embora; transportar 2 trasladar (morto) ♦ méd. 3 levar consigo ou para si 4 fazer levar; fazer pegar (como penhor) 5 sair de, gen. 〈ἔκφορος〉</p></section></article>\n<article id=\"entry-dgp-12884\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφόριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1645 na letra ε · nº geral 12884</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 produto; fruto (da terra) 2 imposto sobre a produção agrícola, equivalente à décima parte da colheita. 〈ἔκφορος〉</p></section></article>\n<article id=\"entry-dgp-12885\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκφορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1646 na letra ε · nº geral 12885</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se pode levar ou exportar 2 que se pode revelar ou divulgar 3 levado para fora de si; desvairado (pela paixão) 4 que divulga (segredo) 5 que arrebata; destruidor de, gen. 〈ἐκφέρω〉</p></section></article>\n<article id=\"entry-dgp-12886\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφορτίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1647 na letra ε · nº geral 12886</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(perf. ἐκπεφόρτισμαι) ser entregue como uma merdadoria; ser abandonado, traído. 〈ἐκ, φόρτος〉</p></section></article>\n<article id=\"entry-dgp-12887\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφράζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1648 na letra ε · nº geral 12887</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 contar; descrever; explicar 2 marcar; designar algo, ac., com algo, dat.</p></section></article>\n<article id=\"entry-dgp-12888\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκφρασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1649 na letra ε · nº geral 12888</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">descrição. 〈ἐκφράζω〉</p></section></article>\n<article id=\"entry-dgp-12889\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφρέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1650 na letra ε · nº geral 12889</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκφρήσω, aor. ἐξέφρησα) levar para fora; fazer sair: ἐξέφρησα ἐμαυτόν luc. eu saí.</p></section></article>\n<article id=\"entry-dgp-12890\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφροντίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1651 na letra ε · nº geral 12890</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">refletir; meditar; imaginar; inventar.</p></section></article>\n";
